package dev.zomboid.scavenging;
import fixture.Game.*;import fixture.Game;import net.minecraft.world.item.ItemStack;import java.util.*;import java.util.zip.*;import java.nio.file.*;
public class QuietChecks{
 static int checks;static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 public static class Actor{public Random random;Actor(long seed){random=new Random(seed);}public Random getRandom(){return random;}}
 static class OriginalLoader extends ClassLoader{final Map<String,byte[]> classes=new HashMap<>();OriginalLoader(Path path)throws Exception{super(QuietChecks.class.getClassLoader());try(ZipFile z=new ZipFile(path.toFile())){for(ZipEntry e:Collections.list(z.entries()))if(e.getName().startsWith("dev/zomboid/scavenging/")&&e.getName().endsWith(".class"))classes.put(e.getName().replace('/','.').replace(".class",""),z.getInputStream(e).readAllBytes());}}protected Class<?>loadClass(String name,boolean resolve)throws ClassNotFoundException{synchronized(getClassLoadingLock(name)){Class<?>found=findLoadedClass(name);if(found==null){byte[]b=classes.get(name);found=b!=null?defineClass(name,b,0,b.length):super.loadClass(name,false);}if(resolve)resolveClass(found);return found;}}}
 static int tools(Corpse b,String word){return b.inventory.items.stream().filter(s->s.item.id.endsWith(word)).mapToInt(ItemStack::getCount).sum();}
 public static void main(String[]args)throws Exception{Game.register();World w=new World();Corpse b=new Corpse();b.lootFinal15=true;b.inventory.setItem(0,Game.stack("minecraft:iron_axe",4));b.inventory.setItem(1,Game.stack("minecraft:diamond_axe",2));Search.Target target=new Search.Target(w,null,null,b,null,"corpse");FinalLoot17.after(target,null);ok(tools(b,"_axe")==1,"Quietly final pass must collapse same tool category");Search.Target playerCorpse=new Search.Target(w,null,null,null,new Object(),"player");FinalLoot17.after(playerCorpse,null);ok(!FinalLoot17.warned,"player Corpse entity path untouched");
 OriginalLoader old=new OriginalLoader(Path.of(args[0]));Class<?> targetClass=old.loadClass("dev.zomboid.scavenging.Search$Target");var ctor=targetClass.getDeclaredConstructors()[0];ctor.setAccessible(true);var bonus=old.loadClass("dev.zomboid.scavenging.Loot").getDeclaredMethod("bonus",targetClass,Object.class,int.class,int.class);bonus.setAccessible(true);
 Corpse before=new Corpse();before.lootFinal15=true;Object oldTarget=ctor.newInstance(w,null,null,before,null,"corpse");bonus.invoke(null,oldTarget,new Actor(4),2,10);int original=tools(before,"_axe")+tools(before,"_pickaxe");ok(original>2,"reproduce original bonus producing stacked identical tools");
 Corpse after=new Corpse();after.lootFinal15=true;Loot.bonus(new Search.Target(w,null,null,after,null,"corpse"),new Actor(4),2,10);ok(tools(after,"_axe")<=1&&tools(after,"_pickaxe")<=1,"patched native bonus executes final normalizer after insertion");ok(!FinalLoot17.warned,"native bonus final bridge works");int otherBefore=before.inventory.items.stream().filter(s->!s.item.id.endsWith("_axe")&&!s.item.id.endsWith("_pickaxe")).mapToInt(ItemStack::getCount).sum(),otherAfter=after.inventory.items.stream().filter(s->!s.item.id.endsWith("_axe")&&!s.item.id.endsWith("_pickaxe")).mapToInt(ItemStack::getCount).sum();ok(otherBefore==otherAfter,"native search non-tool loot unchanged");
 Inv chest=new Inv(54);chest.setItem(0,Game.stack("minecraft:iron_axe",3));Loot.bonus(new Search.Target(w,null,chest,null,null,"chest"),new Actor(4),2,10);ok(chest.items.stream().filter(s->s.item.id.endsWith("_axe")).mapToInt(ItemStack::getCount).sum()<=1,"world chest bonus also limits same tool category");int occupiedLast=0;for(int i=0;i<54;i++)if(!chest.items.get(i).isEmpty())occupiedLast=i;ok(occupiedLast>15,"world chest objects dispersed");
 Inv owned=new Inv(27);ItemStack personal=Game.stack("minecraft:iron_axe",3);owned.setItem(2,personal);owned.tag.putBoolean("QuietlyPlayerPlaced",true);Loot.bonus(new Search.Target(w,null,owned,null,null,"owned"),new Actor(4),2,10);ok(owned.getItem(2)==personal&&personal.getCount()==3,"actual owned storage early return preserves personal tools and slots");
 System.out.println("QUIET_NATIVE_BEFORE_AFTER_CHECKS="+checks+" ORIGINAL_TOOLS="+original+" PATCHED_TOOLS="+(tools(after,"_axe")+tools(after,"_pickaxe")));}
}
